<?php
declare(strict_types=1);
// Uso CLI: php tools/migrate_sqlite_to_mysql.php /caminho/musicroad.sqlite
if(PHP_SAPI!=='cli'){http_response_code(403);exit('Somente CLI.');}
$root=dirname(__DIR__);$source=$argv[1]??'';if($source===''||!is_file($source)){fwrite(STDERR,"Uso: php tools/migrate_sqlite_to_mysql.php /caminho/musicroad.sqlite\n");exit(2);}if(!extension_loaded('pdo_sqlite')){fwrite(STDERR,"PDO SQLite é necessário apenas para a migração.\n");exit(2);}require $root.'/api/bootstrap.php';ensure_schema();$src=new PDO('sqlite:'.$source,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
$tables=['users','plans','licenses','payment_orders','payment_events','music_library','user_music_state','playlists','playlist_tracks','google_tokens','drive_folders','drive_link_checks','client_device_state','radars','radar_sources','road_reports','import_logs','app_settings','audit_logs','address_local_packs','address_local_streets','address_local_points','address_local_street_loads','trial_claims'];$dst=db();$dst->exec('SET FOREIGN_KEY_CHECKS=0');
try{foreach($tables as $table){$exists=$src->query("SELECT name FROM sqlite_master WHERE type='table' AND name=".$src->quote($table))->fetchColumn();if(!$exists){echo "$table: ausente\n";continue;}$rows=$src->query("SELECT * FROM \"$table\"")->fetchAll();if(!$rows){echo "$table: 0\n";continue;}$cols=array_keys($rows[0]);$quoted=array_map(fn($c)=>'`'.str_replace('`','',$c).'`',$cols);$sql='INSERT INTO `'.$table.'`('.implode(',',$quoted).') VALUES('.implode(',',array_fill(0,count($cols),'?')).')';$ins=$dst->prepare($sql);$dst->beginTransaction();$n=0;foreach($rows as $r){try{$ins->execute(array_values($r));$n++;}catch(PDOException $e){if((string)$e->getCode()!=='23000')throw $e;}}$dst->commit();echo "$table: $n\n";}}finally{if($dst->inTransaction())$dst->rollBack();$dst->exec('SET FOREIGN_KEY_CHECKS=1');}foreach(['mercadopago_access_token','mercadopago_webhook_secret','trial_server_secret'] as $k){$v=app_setting($k,'');if($v!=='')set_app_setting($k,$v);}
echo "Migração concluída. Segredos sensíveis foram regravados com criptografia da aplicação. Valide usuários, licenças, pagamentos e radares antes de remover o SQLite antigo.\n";
